param([Parameter(Mandatory=$true)][string]$Path,[int]$Pid=0x0200,[string]$ExtractDirectory="")
$bytes=[IO.File]::ReadAllBytes((Resolve-Path $Path));if($bytes.Length%188){throw "TS size is not a multiple of 188"}
$sections=@();$current=New-Object Collections.Generic.List[byte]
function Flush { while($script:current.Count-ge 3){$n=3+(($script:current[1]-band 15)-shl 8)+$script:current[2];if($script:current.Count-lt$n){break};$script:sections+=,[byte[]]$script:current.GetRange(0,$n).ToArray();$script:current.RemoveRange(0,$n)} }
for($o=0;$o-lt$bytes.Length;$o+=188){if($bytes[$o]-ne0x47){throw "sync lost at $o"};$p=(($bytes[$o+1]-band31)-shl8)+$bytes[$o+2];if($p-ne$Pid){continue};$i=$o+4;$afc=($bytes[$o+3]-shr4)-band3;if($afc-band2){$i+=1+$bytes[$i]};if(-not($afc-band1)-or$i-ge$o+188){continue};if($bytes[$o+1]-band64){$pointer=$bytes[$i++];for($x=0;$x-lt$pointer;$x++){$current.Add($bytes[$i++])};Flush;if($pointer-eq0){$current.Clear()}};while($i-lt$o+188-and$bytes[$i]-ne0xff){$current.Add($bytes[$i++])};Flush}
function U16($b,$i){(($b[$i]-shl8)-bor$b[$i+1])}function U32($b,$i){[uint32](($b[$i]-shl24)-bor($b[$i+1]-shl16)-bor($b[$i+2]-shl8)-bor$b[$i+3])}
$dii=$sections|Where-Object{$_[0]-eq0x3b}|Select-Object -First 1;$ddbs=$sections|Where-Object{$_[0]-eq0x3c};if(-not$dii){throw "DII not found"};$download=U32 $dii 20;$block=U16 $dii 24;$count=U16 $dii 40;$pos=42;$mods=@{}
for($m=0;$m-lt$count;$m++){$id=U16 $dii $pos;$size=U32 $dii ($pos+2);$ver=$dii[$pos+6];$il=$dii[$pos+7];$info=$dii[($pos+8)..($pos+7+$il)];$name=("{0:X4}.bin"-f$id);for($q=0;$q-lt$info.Length-2;){$tag=$info[$q];$len=$info[$q+1];if($tag-eq2){$name=[Text.Encoding]::UTF8.GetString($info,($q+2),$len)};$q+=2+$len};$mods[$id]=[ordered]@{Name=$name;Size=$size;Version=$ver;Data=(New-Object Collections.Generic.List[byte])};$pos+=8+$il}
foreach($s in $ddbs){$id=U16 $s 20;if($mods.ContainsKey($id)-and$s[22]-eq$mods[$id].Version){for($i=26;$i-lt$s.Length-4;$i++){$mods[$id].Data.Add($s[$i])}}}
"DSM-CC PID: 0x{0:X4}`nDownload ID: 0x{1:X8}`nBlock size: {2}`nModules: {3}"-f$Pid,$download,$block,$count
foreach($m in $mods.Values){"{0} version={1} size={2} received={3}"-f$m.Name,$m.Version,$m.Size,$m.Data.Count;if($ExtractDirectory){$root=[IO.Path]::GetFullPath($ExtractDirectory)+[IO.Path]::DirectorySeparatorChar;$full=[IO.Path]::GetFullPath((Join-Path $ExtractDirectory $m.Name));if(-not$full.StartsWith($root)){throw "unsafe module path"};New-Item -ItemType Directory -Force ([IO.Path]::GetDirectoryName($full))|Out-Null;[IO.File]::WriteAllBytes($full,[byte[]]$m.Data.GetRange(0,[Math]::Min($m.Size,$m.Data.Count)).ToArray())}}
